CREATE OR ALTER FUNCTION dbo.CustomerTier (@customerId int)
RETURNS varchar(10) WITH INLINE = OFF
AS
BEGIN
    DECLARE @total decimal(18, 2) =
        (SELECT SUM(Total) FROM dbo.Orders WHERE CustomerId = @customerId);
    RETURN CASE WHEN @total > 5000 THEN 'Gold' ELSE 'Standard' END;
END;
GO
-- Plan: scan 95% of the cost. Tested: ~95% of the time is in the UDF
SELECT o.Id, o.Total, dbo.CustomerTier(o.CustomerId) AS Tier
FROM dbo.Orders AS o
WHERE o.CreatedAt >= '2025-11-01';
